    for (long long i = 0; i < rightsize; i++) {
        right[i] = arr[mid + 1 + i];
    }

    long long i = 0, j = 0, k = start;
    while (i < leftsize && j < rightsize) {
        if (left[i] > right[j]) {
            inv_cnt += leftsize - i;
            arr[k++] = right[j++];
        } else {
            arr[k++] = left[i++];
        }
    }
    while (i < leftsize) {
        arr[k++] = left[i++];
    }
    while (j < rightsize) {
        arr[k++] = right[j++];
    }
}

