        int col = max_finder(mat[mid]);
        if ((mid == 0 || mat[mid][col] > mat[mid - 1][col]) && 
            (mid == n - 1 || mat[mid][col] > mat[mid + 1][col]))
            return {mid, col};
        else {
            if (mid != 0 && mat[mid][col] < mat[mid - 1][col])
                high = mid - 1;
