Node* segregate(Node* head) {
    int zeroCnt = 0, oneCnt = 0, twoCnt = 0;
    Node* curr = head;

    // Count the number of 0s, 1s, and 2s in the linked list
    while (curr) {
        if (curr->data == 0) zeroCnt++;
        if (curr->data == 1) oneCnt++;
        if (curr->data == 2) twoCnt++;
        curr = curr->next;
    }

    curr = head;

    // Overwrite the nodes with 0s, 1s, and 2s based on their counts
    while (zeroCnt) {
        curr->data = 0;
        zeroCnt--;
        curr = curr->next;
    }
    while (oneCnt) {
        curr->data = 1;
        oneCnt--;
        curr = curr->next;
    }
    while (twoCnt) {
        curr->data = 2;
        twoCnt--;
        curr = curr->next;
    }

    return head;
}

Node* reverseLL(Node* head) {
    Node* prev = NULL;
    Node* curr = head;
    while (curr) {
        Node* frwd = curr->next;
        curr->next = prev;
        prev = curr;
        curr = frwd;
    }
    return prev;
}

Node* addOne(Node* head) {
    head = reverseLL(head);
    Node* curr = head;
    int carry = 1;
    Node* last;
    while (curr) {
        long sum = curr->data + carry;
        curr->data = sum % 10;
        carry = sum / 10;
        if (curr && !curr->next)
            last = curr;
        curr = curr->next;
    }
    while (carry) {
        last->next = new Node(carry % 10);
        carry = carry / 10;
        last = last->next;
    }
    head = reverseLL(head);
    return head;
}

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode* p1 = l1;
    ListNode* p2 = l2;
    ListNode* dummy = new ListNode(); // Dummy node to simplify the logic
    ListNode* ans = dummy;
    int sum = 0, carry = 0;
    while (p1 || p2) {
        sum += carry; // Add the carry from the previous step
        if (p1) {
            sum += p1->val;
            p1 = p1->next;
        }
        if (p2) {
            sum += p2->val;
            p2 = p2->next;
        }
        ans->next = new ListNode(sum % 10); // Create a new node with the current digit
        carry = sum / 10; // Update the carry for the next step
        sum = 0;
        ans = ans->next; // Move to the next node in the result linked list
    }
    if (carry) {
        ans->next = new ListNode(carry); // Append the remaining carry as a new node
    }
    return dummy->next; // Return the head of the result linked list (excluding the dummy node)
}

void deleteAllOccurOfX(struct Node** head_ref, int x) {
    Node* curr = *head_ref;
    while (curr) {
        if (curr->data == x) {
            // First node
            if (!curr->prev) {
                *head_ref = curr->next;
                curr->next->prev = NULL
            }
            // Last node
            else if (!curr->next) {
                curr->prev->next = curr->next;
            }
            // Middle node
            else {
                curr->next->prev = curr->prev;
                curr->prev->next = curr->next;
            }
        }
        curr = curr->next;
    }
}

vector<pair<int, int>> findPairsWithGivenSum(Node *head, int target)
{
    vector<pair<int, int>> ans;
    Node* start = head;
    Node* end = head;
    while (end->next) {
        end = end->next;
    }
    while (start->data < end->data) {
        int sum = start->data + end->data;
        if (sum == target) {
            ans.push_back({ start->data, end->data });
            start = start->next;
            end = end->prev;
        }
        else if (sum < target) {
            start = start->next;
        }
        else {
            end = end->prev;
        }
    }
    return ans;
}

Node* removeDuplicates(Node* head)
{
    int dupli = head->data;
    Node* curr = head->next;

    while (curr) {
        while (curr && curr->data == dupli) {
            if (curr->next)
                curr->next->prev = curr->prev;
            curr->prev->next = curr->next;
            curr = curr->next;
        }
        if (curr) {
            dupli = curr->data;
            curr = curr->next;
        }
    }
    return head;
}

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode* ptr = head;
    for (int i = 0; i < k; i++) {
        if (!ptr)
            return head; // Return head if there are less than k nodes remaining
        ptr = ptr->next;
    }
    int count = k;
    ListNode* prev = NULL;
    ListNode* curr = head;
    ListNode* frwd = NULL;
    while (count && curr) {
        frwd = curr->next;
        curr->next = prev;
        prev = curr;
        curr = frwd;
        count--;
    }
    if (frwd)
        head->next = reverseKGroup(frwd, k); // Recursive call for the remaining linked list
    return prev; // Return the new head of the reversed group
}

int find_len(ListNode* head) {
    ListNode* curr = head;
    int cnt = 1;
    while (curr->next) {
        curr = curr->next;
        cnt++;
    }
    curr->next = head; // Connect the last node to the head to form a circular linked list
    return cnt;
}

ListNode* rotateRight(ListNode* head, int k) {
    if (head == NULL || k == 0)
        return head;
    int len = find_len(head); // Find the length of the linked list and form a circular linked list
    k = k % len; // Calculate the actual number of rotations
    ListNode* curr = head;
    // Traverse to the (length - k - 1)th node
    for (int i = 0; i < len - k - 1; i++) {
        curr = curr->next;
    }
    ListNode* newHead = curr->next; // The next node will be the new head
    curr->next = NULL; // Disconnect the new tail from the rest of the list
    return newHead;
}

int getnum(int i, string& str)
{
    if (i < 0)
        return 0;

    if (i == 0) {
        if (str[i] == '-')
            return 0;

        int digit = str[i] - '0';
        if (0 <= digit && digit <= 9) {
            int prev = getnum(i - 1, str);
            if (prev != 1e9)
                return (prev * 10) + digit;
        }
        return 1e9;
    }

    int digit = str[i] - '0';
    if (0 <= digit && digit <= 9) {
        int prev = getnum(i - 1, str);
        if (prev != 1e9)
            return (prev * 10) + digit;
    }
    return 1e9;
}

int atoi(string str)
{
    int i = str.size() - 1;
    int ans = getnum(i, str);
    if (ans == 1e9)
        return -1;
    if (str[0] == '-')
        return -1 * ans;
    return ans;
}

