	if (sum == 0) {
		return 1;
	}
	if (index == 0) {
		return (arr[0] == sum) ? 1 : 0;
	}

	int include = 0;
	if (arr[index] <= sum)
		include = solve(index - 1, sum - arr[index], arr); // include

	int exclude = solve(index - 1, sum, arr); // exclude

	return (include + exclude) % (int)(1e9 + 7);
}

