vector<int> findPrimeFactors(int n) {
    vector<bool> prime(n + 1, true);
    vector<int> ans;

    for (int i = 2; i * i <= n; i++) {
        if (prime[i]) {
            while (n % i == 0) {
                ans.push_back(i);
                n /= i;
            }
            for (long long j = (long long)i * i; j <= n; j += i) {
                prime[j] = false;
            }
        }
    }
    if (n > 1)
        ans.push_back(n);
    return ans;
}

