TreeNode* solve(int pi, int ins, int ine, vector<int>& inorder, vector<int>& postorder) {
    if (pi < 0 || ins > ine) return NULL;

    int loc = -1;
    for (int i = ins; i <= ine; i++) {
        if (inorder[i] == postorder[pi])
            loc = i;
    }

    TreeNode* root = new TreeNode(postorder[pi]);
    root->right = solve(pi - 1, loc + 1, ine, inorder, postorder);
    root->left = solve(pi - (ine - loc + 1), ins, loc - 1, inorder, postorder);

    return root;
}

TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
    int n = inorder.size();
    return solve(n - 1, 0, n - 1, inorder, postorder);
}

vector<int> preOrder(Node* root) {
    vector<int> ans;
    Node* curr = root;

    while (curr) {
        if (!curr->left) {
            ans.push_back(curr->data);
            curr = curr->right;
        } else {
            Node* rightmost = curr->left;
            while (rightmost->right && rightmost->right != curr)
                rightmost = rightmost->right;

            if (!rightmost->right) {
                ans.push_back(curr->data);
                rightmost->right = curr;
                curr = curr->left;
            } else {
                rightmost->right = NULL;
                curr = curr->right;
            }
        }
    }

    return ans;
}

vector<int> inOrder(Node* root) {
    vector<int> ans;
    Node* curr = root;

    while (curr) {
        if (!curr->left) {
            ans.push_back(curr->data);
            curr = curr->right;
        } else {
            Node* rightmost = curr->left;
            while (rightmost->right && rightmost->right != curr)
                rightmost = rightmost->right;

            if (!rightmost->right) {
                rightmost->right = curr;
                curr = curr->left;
            } else {
                ans.push_back(curr->data);
                rightmost->right = NULL;
                curr = curr->right;
            }
        }
    }

    return ans;
}

void flatten(TreeNode* root) {
    TreeNode* curr = root;

    while (curr) {
        if (curr->left) {
            TreeNode* temp = curr->left;
            while (temp->right)
                temp = temp->right;

            temp->right = curr->right;
            curr->right = curr->left;
            curr->left = NULL;
        }
        curr = curr->right;
    }
}

