    q.push({sr, sc});
    int s = ans[sr][sc];
    ans[sr][sc] = color;

    vector<int> dr = {-1, 1, 0, 0};
    vector<int> dc = {0, 0, -1, 1};

    while (!q.empty()) {
        int siz = q.size();
        while (siz--) {
            auto p = q.front();
            q.pop();
            int x = p.first, y = p.second;
            for (int i = 0; i < 4; i++) {
                int nx = x + dr[i], ny = y + dc[i];
                if (nx >= 0 && nx < m && ny >= 0 && ny < n && ans[nx][ny] == s && ans[nx][ny] != color) {
                    ans[nx][ny] = color;
                    q.push({nx, ny});
                }
            }
        }
    }

    return ans;
}

