    vector<bool> vis(N);
    vector<int> dis(N, -1);
    queue<int> q;
    q.push(src);
    vis[src] = true;

    int lvl = 0;
    while(!q.empty()){
        int siz = q.size();
        while(siz--){
            int node = q.front();
            q.pop();
            dis[node] = lvl;
            for(auto v:adj[node]){
                if(!vis[v]){
                    q.push(v);
                    vis[v] = true;
                }
            }
        }
        lvl++;
