// Memoization
int fmemo(int n, vector<int>& dp) {
    if (n == 1 || n == 2)
        return dp[n] = n;
    if (dp[n] != -1)
        return dp[n];
    return dp[n] = fmemo(n - 1, dp) + fmemo(n - 2, dp);
}

// Tabulation
int ftab(int n){
    vector<int> dp(n+1);
    dp[1] = 1, dp[2] = 2;
    for(int i=3; i<=n; i++)
        dp[i] = dp[i-1]+dp[i-2];
    return dp[n];
}

