// Memoization
int fmemo(int i, vector<int>& h, vector<int>& dp) {
    if (i == 0)
        return dp[i] = 0;

    if (dp[i] != -1)
        return dp[i];

    int s1 = INT_MAX, s2 = INT_MAX;
    if (i - 1 >= 0)
        s1 = fmemo(i - 1, h, dp) + abs(h[i - 1] - h[i]);
    if (i - 2 >= 0)
        s2 = fmemo(i - 2, h, dp) + abs(h[i - 2] - h[i]);

    return dp[i] = min(s1, s2);
}

