        if(i-1>=0) s1 = dp[i-1]+abs(h[i-1]-h[i]);
        if(i-2>=0) s2 = dp[i-2]+abs(h[i-2]-h[i]);
        dp[i] = min(s1,s2);
    }
    return dp[n-1];
}

