// Memoization
int fmemo(int i, int k, vector<int>& h, vector<int>& dp) {
    if (i == 0)
        return dp[i] = 0;

    if (dp[i] != -1)
        return dp[i];

    int ans = INT_MAX, temp = INT_MAX;
    for (int j = 1; j <= k; j++) {
        if (i - j >= 0)
            temp = fmemo(i - j, k, h, dp) + abs(h[i] - h[i - j]);
        ans = min(ans, temp);
    }

    return dp[i] = ans;
}

// Tabulation
int ftab(int i, int k, vector<int>& h){
    int n = h.size();
    vector<int> dp(n,INT_MAX);
    dp[0] = 0;

    int temp = INT_MAX;
    for(int i=1; i<n; i++){
        for(int j=1; j<=k; j++){
            if(i-j >= 0) temp = dp[i-j]+abs(h[i]-h[i-j]);
            dp[i] = min(dp[i],temp);
        }
    }
    return dp[n-1];
}

