    if(dp[i][tar] != -1) return dp[i][tar];

    int take = 0;
    if(arr[i] <= tar) take = fmemo(i - 1, tar - arr[i], arr, dp);
    int notake = fmemo(i - 1, tar, arr, dp);
    return dp[i][tar] = (take + notake);
}

