int ftab(int n, vector<int>& nums) {
    vector<int> dp(n, 1);
    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[prev] < nums[i]) {
                dp[i] = max(dp[prev] + 1, dp[i]);
            }
        }
    }
    int ans = -1;
    for (auto i : dp) ans = max(ans, i);
    return ans;
}

