vector<int> ftab(int n, vector<int>& nums) {
    vector<int> dp(n, 1);
    vector<int> prevmap(n, -1);

    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[i] % nums[prev] == 0 && dp[i] < dp[prev] + 1) {
                dp[i] = dp[prev] + 1;
                prevmap[i] = prev;
            }
        }
    }

    int i = max_element(dp.begin(), dp.end()) - dp.begin();
    vector<int> lis;

    while (i >= 0) {
        lis.push_back(nums[i]);
        i = prevmap[i];
    }

    return lis;
}

