vector<int> fromLeft(int n, vector<int>& nums) {
    vector<int> dp(n, 1);
    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[prev] < nums[i]) {
                dp[i] = max(dp[prev] + 1, dp[i]);
            }
        }
    }
    return dp;
}

vector<int> fromRight(int n, vector<int>& nums) {
    vector<int> dp(n, 1);
    for (int i = n - 1; i >= 0; i--) {
        for (int prev = i + 1; prev < n; prev++) {
            if (nums[prev] < nums[i]) {
                dp[i] = max(dp[prev] + 1, dp[i]);
            }
        }
    }
    return dp;
}

int LongestBitonicSequence(vector<int> nums) {
    int n = nums.size();
    vector<int> left = fromLeft(n, nums);
    vector<int> right = fromRight(n, nums);

    int ans = -1;
    for (int i = 0; i < n; i++) {
        ans = max(ans, left[i] + right[i] - 1);
    }

    return ans;
}

int ftab(int n, vector<int>& nums) {
    vector<int> dp(n, 1);
    vector<int> cnt(n, 1);

    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[prev] < nums[i]) {
                if (dp[i] == dp[prev] + 1) {
                    cnt[i] += cnt[prev];
                } else if (dp[prev] + 1 > dp[i]) {
                    dp[i] = dp[prev] + 1;
                    cnt[i] = cnt[prev];
                }
            }
        }
    }

    int lis = *max_element(dp.begin(), dp.end());
    int ans = 0;

    for (int i = 0; i < n; i++) {
        if (dp[i] == lis) {
            ans += cnt[i];
        }
    }

    return ans;
}

