    vector<vector<int>> dp(n, vector<int>(n, -1));
    return fmemo(i, j, nums, dp);
}

bool isPalindrome(int i, int j, string& s){
    while(i < j){
        if(s[i] != s[j]) return false;
        i++; j--;
    }
    return true;
}

int fmemo(int i, string& s, vector<int>& dp){
    if(i == s.size()) return 0;

    if(dp[i] != -1) return dp[i];

    int ans = 1e9;
    for(int j = i; j < s.size(); j++){
        if(isPalindrome(i, j, s)){
            int cost = 1 + fmemo(j + 1, s, dp);
            ans = min(ans, cost);
        }
    }
    return dp[i] = ans;
}

int minCut(string s) {
    int n = s.size();
    vector<int> dp(n, -1);
    return fmemo(0, s, dp) - 1;
}

int fmemo(int i, int k, vector<int>& arr, vector<int>& dp){
    if(i == arr.size()) return 0;

    if(dp[i] != -1) return dp[i];

    int n = arr.size();
    int maxi = 0, ans = 0;
    for(int j = i; j < min(i + k, n); j++){
        maxi = max(maxi, arr[j]);
        int maxSum = maxi * (j - i + 1) + fmemo(j + 1, k, arr, dp);
        ans = max(ans, maxSum);
    }
    return dp[i] = ans;
}

int maxSumAfterPartitioning(vector<int>& arr, int k) {
    int n = arr.size();
    vector<int> dp(n, -1);
    return fmemo(0, k, arr, dp);
}

// Helper function to calculate the previous smaller element index for each element in an array
vector<int> prevSmaller(vector<int>& arr) {
    stack<int> st;
    vector<int> ans(arr.size(), -1);
    for (int i = 0; i < arr.size(); i++) {
        while (!st.empty() && arr[st.top()] > arr[i])
            st.pop();
        if (!st.empty())
            ans[i] = st.top();
        st.push(i);
    }
    return ans;
}

// Helper function to calculate the next smaller element index for each element in an array
vector<int> nextSmaller(vector<int>& arr) {
    stack<int> st;
    vector<int> ans(arr.size(), arr.size());
    for (int i = arr.size() - 1; i >= 0; i--) {
        while (!st.empty() && arr[st.top()] >= arr[i])
            st.pop();
        if (!st.empty())
            ans[i] = st.top();
        st.push(i);
    }
    return ans;
}

// Function to calculate the largest rectangle area in a histogram represented by heights
int largestRectangleArea(vector<int>& heights) {
    vector<int> prev = prevSmaller(heights);
    vector<int> next = nextSmaller(heights);

    int ans = INT_MIN;
    for (int i = 0; i < heights.size(); i++) {
        ans = max(ans, (next[i] - prev[i] - 1) * heights[i]);
    }
    return ans;
}

// Function to find the largest rectangle area in a binary matrix
int maximalRectangle(vector<vector<char>>& matrix) {
    if (matrix.empty() || matrix[0].empty())
        return 0;

    int rows = matrix.size();
    int cols = matrix[0].size();
    vector<int> prev(cols, 0);
    int maxArea = 0;

    for (int i = 0; i < rows; i++) {
        vector<int> curr(cols, 0);
        for (int j = 0; j < cols; j++) {
            if (matrix[i][j] == '1')
                curr[j] = prev[j] + 1;
        }

        int rowArea = largestRectangleArea(curr);
        maxArea = max(maxArea, rowArea);

        prev = curr;
    }

    return maxArea;
}

/*
COMPLEXITY ANALYSIS:
- Let n be the total number of elements in the matrix, and m be the number of columns.
- The time complexity of the solution is O(n*m) because we iterate through each element of the matrix once.
- The space complexity is O(m) since we use additional arrays to store the heights and indices during the calculation.
  However, the space complexity can be considered O(1) if we modify the input matrix directly.
*/

int ftab(int m, int n, vector<vector<int>>& matrix){
    vector<vector<int>> dp(m+1, vector<int>(n+1, 0));
    int ans = 0;
    for(int i = 1; i <= m; i++){
        for(int j = 1; j <= n; j++){
            if(matrix[i-1][j-1] == 1){
                int temp = min(dp[i-1][j], dp[i-1][j-1]);
                dp[i][j] = min(dp[i][j-1], temp) + 1;
                ans += dp[i][j];
            }
        }
    }
    return ans;
}

int countSquares(vector<vector<int>>& matrix) {
    int m = matrix.size(), n = matrix[0].size();
    return ftab(m, n, matrix);
}

class TrieNode {
public:
    TrieNode* children[26];
    bool end;

    TrieNode() {
        this->end = false;
        for (int i = 0; i < 26; i++) {
            this->children[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(string& word) {
        TrieNode* curr = root;
        int n = word.size();
        for (int i = 0; i < n; i++) {
            int key = word[i] - 'a';
            if (curr->children[key] == NULL) {
                curr->children[key] = new TrieNode();
            }
            curr = curr->children[key];
        }
        curr->end = true;
    }

    bool isvalid(string& word) {
        TrieNode* curr = root;
        int n = word.size();
        for (int i = 0; i < n; i++) {
            int key = word[i] - 'a';
            if (curr->children[key] == NULL || curr->children[key]->end == false) {
                return false;
            }
            curr = curr->children[key];
        }
        return curr != NULL && curr->end;
    }
};

string completeString(int n, vector<string>& a) {

    Trie tr;

    for (auto it : a) {
        tr.insert(it);
    }

    string ans = "";

    for (auto it : a) {
        if (tr.isvalid(it)) {
            if (ans.size() < it.size())
                ans = it;
            else if (ans.size() == it.size() && it < ans)
                ans = it;
        }
    }
    if (ans.size() == 0)
        return "None";
    return ans;

}

