class TrieNode {
public:
    TrieNode* child[2];

    TrieNode() {
        for(int i = 0; i < 2; i++) {
            this->child[i] = NULL;
        }
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(int num) {
        TrieNode* curr = root;
        for(int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if(!curr->child[bit]) {
                curr->child[bit] = new TrieNode();
            }
            curr = curr->child[bit];
        }
    }

    int findMax(int num) {
        TrieNode* curr = root;
        int maxNum = 0;
        for(int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if(curr->child[1 - bit]) {
                maxNum = maxNum | (1 << i);
                curr = curr->child[1 - bit];
            } else {
                curr = curr->child[bit];
            }
        }
        return maxNum;
    }
};

class Solution {
public:
    int findMaximumXOR(vector<int>& nums) {
        Trie* tr = new Trie();
        for(auto i : nums) {
            tr->insert(i);
        }
        int ans = 0;
        for(auto i : nums) {
            int temp = tr->findMax(i);
            ans = max(ans, temp);
        }
        return ans;
    }
};

int minAddToMakeValid(string s) {
    int open = 0, close = 0;
    for(char c : s) {
        if(c == '(') {
            open++;
        } else {
            if(open > 0) {
                open--; // balance it with an open parenthesis
            } else {
                close++;
            }
        }
    }
    return open + close; // total moves required
}

string countAndSay(int n) {
    if(n == 1) {
        return "1";
    }
    string prev = countAndSay(n - 1);
    string ans = "";
    for(int i = 0; i < prev.size(); i++) {
        int j = i + 1;
        while(j < prev.size() && prev[j - 1] == prev[j]) {
            j++;
        }
        ans += to_string(j - i) + prev[i];
        i = j - 1;
    }
    return ans;
}

vector<int> lps(string& s){
    int n = s.size();
    vector<int> pi(n);
    for(int i = 1; i < n; i++){
        int j = pi[i - 1];
        while(j > 0 && s[j] != s[i]) {
            j = pi[j - 1];
        }
        if(s[j] == s[i]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

int strStr(string haystack, string needle) {
    if(needle.empty()) {
        return 0;
    }
    string temp = needle + '$' + haystack;
    vector<int> lpsArray = lps(temp);
    for(int i = 0; i < lpsArray.size(); i++) {
        if(lpsArray[i] == needle.size()) {
            return i - 2 * needle.size();
        }
    }
    return -1;
}

